function validate(input) {
  const [{ Products = [], Orders = [] }] = input;
  const products = new Set();
  for (const [id] of Products) {
    if (id === null) return 'Every product needs a product_id.';
    if (products.has(id)) return `product_id ${id} appears twice in Products.`;
    products.add(id);
  }
  for (const [id, day, unit] of Orders) {
    if (!products.has(id)) return `An order names unknown product ${id}.`;
    if (day === null || !/^\d{4}-\d{2}-\d{2}$/.test(day) || Number.isNaN(Date.parse(`${day}T00:00:00Z`))) return `${day} is not an order date.`;
    if (unit === null || unit < 1) return `Product ${id} has an order with unit ${unit}; units are positive.`;
  }
  return null;
}

