function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const categories = ['Book', 'Laptop', 'T-shirt', 'Phone'];
  const productCount = small ? Math.floor(rand() * 6) : 300;
  const Products = [], Orders = [];
  // Names are unique per product, so grouping by name or by id agrees.
  for (let id = 1; id <= productCount; id++) Products.push([id, `Product ${id}`, pick(categories)]);
  if (productCount === 0) return [{ Products, Orders }];
  const smallDates = ['2020-01-31', '2020-02-01', '2020-02-10', '2020-02-29', '2020-03-01', '2019-02-14', '2021-02-14'];
  const smallUnits = [10, 30, 40, 50, 60, 70, 100];
  const orderCount = small ? Math.floor(rand() * 9) : 2000;
  for (let i = 0; i < orderCount; i++) {
    const id = 1 + Math.floor(rand() * productCount);
    if (small) { Orders.push([id, pick(smallDates), pick(smallUnits)]); continue; }
    // Large: dates from 2020-01-01 through 2020-03-31, so about a third fall in February.
    const day = new Date(Date.UTC(2020, 0, 1) + Math.floor(rand() * 91) * 86400000).toISOString().slice(0, 10);
    Orders.push([id, day, 1 + Math.floor(rand() * 40)]);
  }
  return [{ Products, Orders }];
}
